import {
	ChangeDetectionStrategy,
	ChangeDetectorRef,
	Component,
	Inject,
	Input,
	OnDestroy,
	OnInit,
	PLATFORM_ID,
} from '@angular/core';

import { CommonModule, DOCUMENT, isPlatformBrowser } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { ActivatedRoute } from '@angular/router';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';

import { TranslationService } from '../../../core/services/translation.service';
import { PaymentsService } from '../../../providers/payments/payments.service';
import { PhoneInputComponent } from '../../../shared/phone-input/phone-input.component';
import { environment } from '../../../../environments/environment';
import { LucideAngularModule } from 'lucide-angular';

interface CostPlan {
	plan_name: string;
	plan_name_ar: string;
	title: string;
	title_ar: string;
	description: string;
	description_ar: string;
	long_description_ar: string;
	long_description: string;
	amount: number;
	amount_usd: number;
	duration: string;
	duration_ar: string;
	features: string[];
	features_ar: string[];
	featured: boolean;
}

@Component({
	selector: 'app-cost-card',
	standalone: true,
	imports: [
		CommonModule,
		TranslateModule,
		ReactiveFormsModule,
		PhoneInputComponent,
		LucideAngularModule,
	],
	templateUrl: './cost-card.component.html',
	styleUrl: './cost-card.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CostCardComponent implements OnInit, OnDestroy {
	@Input() category: string = '';
	@Input() consultationLink = '/branding#packages';
	@Input() currency: 'AED' | 'USD' = 'AED';

	plans: CostPlan[] = [];
	baseUrl: string;

	isBookingModalOpen = false;
	isBookingSubmitted = false;
	bookingErrorMessage = '';
	bookingForm: FormGroup;
	selectedPlanForBooking: CostPlan | null = null;

	constructor(
		private route: ActivatedRoute,
		private paymentservice: PaymentsService,
		private cdr: ChangeDetectorRef,
		private formBuilder: FormBuilder,
		public translationService: TranslationService,
		@Inject(PLATFORM_ID) private platformId: Object,
		@Inject(DOCUMENT) private document: Document,
	) {
		this.baseUrl = environment.url;
		this.bookingForm = this.formBuilder.group({
			firstname: ['', Validators.required],
			lastname: ['', Validators.required],
			email: [
				'',
				[
					Validators.required,
					Validators.email,
					Validators.pattern('^[a-z0-9._%+-]+@[a-z0-9.-]+\\.[a-z]{2,4}$'),
				],
			],
			contact: this.formBuilder.group({
				phone: ['', Validators.required],
				countryCode: ['+971'],
			}),
			company: ['', Validators.required],
			website: [''],
			customer_message: [''],
		});
	}

	ngOnInit() {
		if (!this.category) {
			this.category = this.route.snapshot.routeConfig?.path || '';
		}
		this.getPackages();
	}

	ngOnDestroy() {
		this.setBodyScrollLocked(false);
	}

	private setBodyScrollLocked(locked: boolean) {
		if (!isPlatformBrowser(this.platformId)) return;
		this.document.body.style.overflow = locked ? 'hidden' : '';
	}

	private getPackages() {
		this.paymentservice.getFilterPackages({}).subscribe((res: any) => {
			if (res?.body?.code !== 200) return;

			const packages: any[] = res.body.result || [];

			this.plans = packages
				.filter(
					(pkg: any) => pkg.packagecategory_name?.toLowerCase() === this.category?.toLowerCase(),
				)
				.sort((a: any, b: any) => (a.sequence_number || 0) - (b.sequence_number || 0))
				.map((pkg: any) => this.toCostPlan(pkg));

			this.cdr.markForCheck();
		});
	}

	private toCostPlan(pkg: any): CostPlan {
		const features: string[] = pkg.features || [];
		const featuresAr: string[] = pkg.features_ar || [];

		return {
			plan_name: pkg.plan_name,
			plan_name_ar: pkg.plan_name_ar,

			title: pkg.title,
			title_ar: pkg.title_ar,

			description: pkg.description,
			description_ar: pkg.description_ar,

			long_description: pkg.long_description,
			long_description_ar: pkg.long_description_ar,

			amount: pkg.amount,
			amount_usd: pkg.amount_usd,

			// Duration comes from the admin description field
			duration: pkg.description || '',
			duration_ar: pkg.description_ar || '',

			features: features,
			features_ar: featuresAr,

			featured: !!pkg.isFeatured,
		};
	}

	onPhoneChange(value: any) {
		this.bookingForm.get('contact')?.patchValue({
			phone: value.number,
			countryCode: value.internationalNumber.replace(value.number, ''),
		});
	}

	openBookingModal(plan: CostPlan) {
		this.bookingErrorMessage = '';
		this.selectedPlanForBooking = plan;
		this.isBookingModalOpen = true;
		this.setBodyScrollLocked(true);
		this.cdr.markForCheck();
	}

	closeBookingModal() {
		this.isBookingModalOpen = false;
		this.setBodyScrollLocked(false);
		this.cdr.markForCheck();
	}

	submitBooking() {
		this.isBookingSubmitted = true;
		this.bookingErrorMessage = '';

		if (this.bookingForm.invalid) {
			this.bookingForm.markAllAsTouched();
			return;
		}

		const contact = this.bookingForm.value.contact;

		const payload = {
			email: this.bookingForm.value.email,
			customer_name: this.bookingForm.value.firstname,
			firstname: this.bookingForm.value.firstname,
			lastname: this.bookingForm.value.lastname,
			contact: (contact?.countryCode || '') + (contact?.phone || ''),
			company: this.bookingForm.value.company,
			website: this.bookingForm.value.website,
			customer_message: this.bookingForm.value.customer_message,
			type: this.selectedPlanForBooking?.plan_name || this.category,
			base_url: this.baseUrl,
		};

		this.paymentservice.stripePayments(payload).subscribe({
			next: (response) => {
				if (response.body?.code === 200) {
					this.closeBookingModal();
					this.isBookingSubmitted = false;
					this.bookingForm.reset({ contact: { countryCode: '+971' } });

					this.showAlert({
						icon: 'success',
						html:
							this.translationService.currentLang() === 'ar'
								? '<h1>شكراً لك</h1> <br> <h6>على تقديم طلبك!<h6> <br> <p>يسعدنا مساعدتك في رحلة العلامة التجارية الخاصة بك!</p> <br><p>سيتصل بك أحد أعضاء فريقنا قريباً لمناقشة المتطلبات!</p>'
								: "<h1>Thank you</h1> <br> <h6>For submitting you request!<h6> <br> <p> We're thrilled to assist you with your Branding Journey!</p> <br><p> One of our team members will contact you shortly to discuss requirements!</p>",
						showConfirmButton: true,
						confirmButtonText:
							this.translationService.currentLang() === 'ar'
								? 'بالتأكيد! أتطلع إلى ذلك'
								: 'Sure! Looking forward',
						customClass: {
							confirmButton: 'success-button',
						},
					});
					this.cdr.markForCheck();
				} else {
					this.bookingErrorMessage =
						this.translationService.currentLang() === 'ar'
							? 'فشل إرسال رسالتك. يرجى المحاولة مرة أخرى لاحقاً.'
							: 'Failed to send your message. Please try again later.';
					this.cdr.markForCheck();
				}
			},
			error: () => {
				this.bookingErrorMessage =
					this.translationService.currentLang() === 'ar'
						? 'فشل إرسال رسالتك. يرجى المحاولة مرة أخرى لاحقاً.'
						: 'Failed to send your message. Please try again later.';
				this.cdr.markForCheck();
			},
		});
	}

	async showAlert(options: any) {
		const Swal = (await import('sweetalert2')).default;
		return Swal.fire(options);
	}

	public hasError = (controlName: string, errorName: string) => {
		return this.bookingForm.controls[controlName].hasError(errorName);
	};

	public hasEmailError = (errorName: string) => {
		const isArabic = this.translationService.currentLang() === 'ar';
		const emailRequired = isArabic ? 'البريد الإلكتروني مطلوب.' : 'Email is required';
		const invalidEmail = isArabic ? 'يرجى إدخال بريد إلكتروني صحيح.' : 'Invalid Email';

		const ctrl = this.bookingForm.controls['email'];
		if (ctrl.value === '') {
			return emailRequired;
		} else if (ctrl.status === 'INVALID') {
			return invalidEmail;
		}
		return ctrl.hasError(errorName);
	};
}
